package com.betvima.app.ui

/**
 * Editorial guidance for the four Information entries in the native app.
 * This is explanatory content, not a replacement for server decisions, legally
 * applicable terms, supported-country checks or the published website policies.
 */
internal data class FooterInfoSection(
    val headingEn: String,
    val headingFa: String,
    val bodyEn: String,
    val bodyFa: String
)

internal data class FooterInfoArticle(
    val id: String,
    val titleEn: String,
    val titleFa: String,
    val subtitleEn: String,
    val subtitleFa: String,
    val summaryEn: String,
    val summaryFa: String,
    val sourceUrl: String,
    val sections: List<FooterInfoSection>
)

private fun section(
    en: String, fa: String, enText: String, faText: String
) = FooterInfoSection(en, fa, enText.trimIndent(), faText.trimIndent())

internal fun footerInfoArticle(id: String): FooterInfoArticle? = when (id) {
