internal fun footerInfoValid(id: String) =
    footerInfoArticle(id)?.let { article ->
        article.sections.size >= 7 &&
            article.sections.all { it.headingEn.isNotBlank() && it.headingFa.isNotBlank()
                && it.bodyEn.isNotBlank() && it.bodyFa.isNotBlank() } &&
            article.sourceUrl.startsWith("https://betvima.com")
    } ?: false
